class ExpenseClaimSerializer(serializers.ModelSerializer):
    payout_bank_account = serializers.PrimaryKeyRelatedField(
        queryset=BankAccount.objects.none()
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get('request')
        if request and request.user.is_authenticated:
            self.fields['payout_bank_account'].queryset = BankAccount.objects.filter(user=request.user)

    class Meta:
        model = ExpenseClaim
        fields = ['id', 'amount', 'category', 'description', 'payout_bank_account']
